    let active_style = Style::new().bold();
    let inactive_prefix = Style::new().dim();
    let inactive_style = Style::new().dim();

    // Write prompt question
    term.write_line(&prompt.question).map_err(BivvyError::Io)?;
    term.hide_cursor().map_err(BivvyError::Io)?;

    // Helper closure to clean up terminal state on exit (success or error).
    let cleanup = |term: &Term, options_drawn: bool, options_len: usize| {
        if options_drawn {
            let _ = term.clear_last_lines(options_len);
        }
        let _ = term.show_cursor();
    };

    let mut options_drawn = false;

    loop {
        // Draw option lines
        for (i, opt) in options.iter().enumerate() {
            let line = if i == sel {
                format!(
                    "{}{} {}",
                    pad,
                    active_prefix.apply_to("›"),
                    active_style.apply_to(&opt.label)
                )
            } else {
                format!(
                    "{}{} {}",
                    pad,
                    inactive_prefix.apply_to("·"),
                    inactive_style.apply_to(&opt.label)
                )
            };
            term.write_line(&line).map_err(|e| {
                cleanup(term, options_drawn, options.len());
                BivvyError::Io(e)
            })?;
        }
        options_drawn = true;
        term.flush().map_err(|e| {
            cleanup(term, options_drawn, options.len());
            BivvyError::Io(e)
        })?;

        // Read key — handle EOF/errors by restoring terminal state
        let key = match term.read_key() {
            Ok(key) => key,
            Err(e) => {
                cleanup(term, options_drawn, options.len());
                return Err(BivvyError::Io(std::io::Error::new(
                    std::io::ErrorKind::Interrupted,
                    format!("Prompt cancelled: {}", e),
                )));
            }
        };

        // Treat Ctrl+D as cancellation
        if is_ctrl_d(&key) {
            cleanup(term, options_drawn, options.len());
            return Err(cancelled_error());
        }

        let chosen = match key {
            Key::Char('y') | Key::Char('Y') => options.iter().position(|o| o.value == "yes"),
            Key::Char('n') | Key::Char('N') => options.iter().position(|o| o.value == "no"),
            Key::Enter | Key::Char(' ') => Some(sel),
            Key::ArrowDown | Key::Tab | Key::Char('j') => {
